 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
+    // Initialize histograms to zero
     for (int b = 0; b < 256; ++b) hist[b] = 0;
+    
+    if (n == 0) return;
+    
+    // NUM_SUB_HISTS private sub-histograms to avoid store-to-load dependency chains on hot bins
+    constexpr int NUM_SUB_HISTS = 8;
+    alignas(16) uint32_t sub_hists[NUM_SUB_HISTS][256];
+    for (int s = 0; s < NUM_SUB_HISTS; ++s) {
+        for (int b = 0; b < 256; ++b) sub_hists[s][b] = 0;
+    }
+    
+    // UNROLL_FACTOR for the main processing loop
+    constexpr int UNROLL_FACTOR = 4;
+    
+    size_t i = 0;
+    
+    // Vectorized prefix sum with sub-histogram updates using NEON
+#if defined(__ARM_NEON)
+    int64x2_t sum_vec = vdupq_n_s64(0);
+    
+    // Process UNROLL_FACTOR elements at a time with NEON
+    for (; i + UNROLL_FACTOR <= n; i += UNROLL_FACTOR) {
+        // Load UNROLL_FACTOR int64 values
+        int64x2_t vals[UNROLL_FACTOR / 2];
+        vals[0] = vld1q_s64(in + i);
+        
+        if (UNROLL_FACTOR >= 4) {
+            vals[1] = vld1q_s64(in + i + 2);
+        }
+        
+        // Compute prefix sum using pairwise additions
+        int64x2_t acc = sum_vec;
+        
+        if (UNROLL_FACTOR == 4) {
+            acc = vaddq_s64(acc, vals[0]);
+            out[i] = vgetq_lane_s64(acc, 0);
+            sub_hists[(i + 0) & (NUM_SUB_HISTS - 1)][(int64_t(in[i]) & 255)]++;
+            
+            acc = vaddq_s64(acc, vals[1]);
+            out[i + 1] = vgetq_lane_s64(acc, 1);
+            sub_hists[(i + 1) & (NUM_SUB_HISTS - 1)][(int64_t(in[i + 1]) & 255)]++;
+            
+            out[i + 2] = vgetq_lane_s64(acc, 0);
+            sub_hists[(i + 2) & (NUM_SUB_HISTS - 1)][(int64_t(in[i + 2]) & 255)]++;
+            
+            acc = vaddq_s64(acc, vals[1]);
+            out[i + 3] = vgetq_lane_s64(acc, 1);
+            sub_hists[(i + 3) & (NUM_SUB_HISTS - 1)][(int64_t(in[i + 3]) & 255)]++;
+        }
+        
+        sum_vec = acc;
+    }
+#else
     int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
