+        int64_t v0 = in[i];
+        int64_t v1 = in[i + 1];
+        int64_t v2 = in[i + 2];
+        int64_t v3 = in[i + 3];
+        
+        sum += v0;
+        out[i] = sum;
+        sub_hists[i & (NUM_SUB_HISTS - 1)][v0 & 255]++;
+        
+        sum += v1;
+        out[i + 1] = sum;
+        sub_hists[(i + 1) & (NUM_SUB_HISTS - 1)][v1 & 255]++;
+        
+        sum += v2;
+        out[i + 2] = sum;
+        sub_hists[(i + 2) & (NUM_SUB_HISTS - 1)][v2 & 255]++;
+        
+        sum += v3;
+        out[i + 3] = sum;
