+            sum += in[i];
+            out[i] = sum;
+            sub_hists[i & (NUM_SUB_HISTS - 1)][in[i] & 255]++;
+        }
+    }
+#else
+    for (; i < n; ++i) {
         sum += in[i];
         out[i] = sum;
-        hist[in[i] & 255]++;
+        sub_hists[i & (NUM_SUB_HISTS - 1)][in[i] & 255]++;
+    }
+#endif
+    
+    // Merge sub-histograms into final histogram
+    for (int b = 0; b < 256; ++b) {
+        uint64_t total = 0;
+        for (int s = 0; s < NUM_SUB_HISTS; ++s) {
+            total += sub_hists[s][b];
+        }
+        hist[b] = total;
     }
 }
